/* Подложка, грифы и заверение копий (Документы). Подложка и колонтитулы — параметры страницы документа:
   они уходят в .docx (водяной знак в колонтитуле), .odt и печать. Экземпляры с номерами — архивом:
   для каждого номера колонтитул меняется, документ собирается в байты, потом всё возвращается как было. */
const ЗЕЛЁНЫЙ = '#2b8a3e', КРАСНЫЙ = '#c92a2a', СЕРЫЙ = '#868e96';
const экран = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
let выбрана = null;   /* картинка подложки: {данные: 'data:…', имя} */
async function безСбоя(f){ try { return await f(); } catch(e){ панель.сообщение(e.message); } }

function Старт(){
  /* заверитель и организация — из прошлого раза */
  for(const k of ['должность', 'фио', 'организация', 'дело']){ const v = хранилище.взять(k, ''); if(v) панель.поле(k, v); }
  показатьСейчас();
}
function показатьСейчас(){
  const с = документ.страница || {}, п = с.подложка, к = с.колонтитулы || {};
  const части = [];
  if(!п) части.push({текст: 'Подложки нет', цвет: СЕРЫЙ});
  else if(п.картинка) части.push({текст: 'Сейчас: картинка, ' + Math.round((п.масштаб || 0.6) * 100) + '% ширины', жирный: true});
  else части.push({текст: 'Сейчас: «' + п.текст + '»', жирный: true}, {текст: ', ' + (Math.abs(п.угол || 0) > 1 ? 'по диагонали' : 'горизонтально') + ', ' + Math.round((п.прозрачность || 0) * 100) + '%'});
  const гриф = [к.верх, к.верхСправа].filter(Boolean).find(т => ГРИФЫ.test(т));
  if(гриф) части.push({текст: '\nГриф в колонтитуле: ' + гриф});
  панель.поле('сейчас', части);
}

/* ---------- подложка ---------- */
function ПоставитьПодложку(){ return безСбоя(() => {
  const п = параметры({});
  const прозр = Math.max(0.05, Math.min(1, (+п.прозрачность || 25) / 100));
  if(п.вид === 'Картинка'){
    if(!выбрана) throw new Error('Сначала «Выбрать картинку…»: PNG, JPEG, GIF или WebP');
    документ.подложка({картинка: выбрана.данные, прозрачность: прозр, масштаб: Math.max(0.1, Math.min(1, (+п.масштаб || 60) / 100))});
  } else {
    const текст = (п.надпись === 'Свой текст' ? String(п.свой || '') : п.надпись || '').trim();
    if(!текст) throw new Error('Впишите свою надпись');
    const диаг = п.наклон !== 'Горизонтально';
    /* кегль по длине: надпись должна лечь в лист (диагональ A4 ~ 1000 пт, ширина ~ 520 пт), буква ~ 0,62 кегля */
    const место = диаг ? 760 : 470, сам = Math.round(Math.max(24, Math.min(120, место / (текст.length * 0.62))));
    документ.подложка({текст, угол: диаг ? -45 : 0, прозрачность: прозр, кегль: +п.кегль > 0 ? +п.кегль : сам, цвет: /^#[0-9a-f]{6}$/i.test(п.цвет || '') ? п.цвет : '#808080'});
  }
  показатьСейчас();
  панель.сообщение('Подложка стоит на всех страницах; «Отменить» в документе её снимет');
}); }
function УбратьПодложку(){ return безСбоя(() => { документ.подложка(null); показатьСейчас(); панель.сообщение('Подложка убрана'); }); }
function base64(б){ let s = ''; for(let i = 0; i < б.length; i += 0x8000) s += String.fromCharCode.apply(null, б.subarray(i, i + 0x8000)); return btoa(s); }
function типКартинки(б){
  if(б[0] === 0x89 && б[1] === 0x50) return 'png';
  if(б[0] === 0xFF && б[1] === 0xD8) return 'jpeg';
  if(б[0] === 0x47 && б[1] === 0x49) return 'gif';
  if(б[8] === 0x57 && б[9] === 0x45 && б[10] === 0x42 && б[11] === 0x50) return 'webp';
  return null;
}
async function ВыбратьКартинку(){ return безСбоя(async () => {
  const ф = await файл.выбрать({типы: ['.png', '.jpg', '.jpeg', '.gif', '.webp'], зачем: 'картинка для подложки'});
  if(!ф || !ф.length) return;
  const б = ф[0].байты, тип = типКартинки(б);
  if(!тип) throw new Error('Это не картинка PNG, JPEG, GIF или WebP: ' + ф[0].имя);
  let данные = 'data:image/' + тип + ';base64,' + base64(б);
  if(данные.length > 3800000){
    /* большая фотография — уменьшаем на странице до разумного */
    const м = await картинка.преобразовать(б, {масштаб: Math.sqrt(2600000 / данные.length), тип: 'jpeg', качество: 0.85});
    данные = м.данные;
  }
  выбрана = {данные, имя: ф[0].имя};
  панель.поле('вид', 'Картинка');
  панель.поле('картинка', [{текст: ф[0].имя, жирный: true}, {текст: ' — ' + Math.round(данные.length * 0.75 / 1024) + ' КБ. Нажмите «Поставить подложку».'}]);
}); }

/* ---------- гриф ---------- */
const ГРИФЫ = /служебного пользования|конфиденциально|коммерческая тайна|экз\. №/i;
function текстГрифа(п, номер){
  const г = п.гриф === 'Свой' ? String(п.свойГриф || '').trim() : п.гриф;
  if(!г) throw new Error('Впишите свой гриф');
  const части = [г];
  if(п.гриф === 'Коммерческая тайна' && String(п.обладатель || '').trim()) части.push(String(п.обладатель).trim().replace(/\s*\n\s*/g, ', '));
  if(п.сНомером) части.push('Экз. № ' + (номер || Math.max(1, +п.экз || 1)));
  return части;
}
function ПоставитьГриф(){ return безСбоя(() => {
  const п = параметры({});
  const части = текстГрифа(п);
  if(п.гдеГриф === 'Первым абзацем, справа'){
    снятьАбзацГрифа();
    документ.вставить(0, '<p style="text-align:right">' + части.map(экран).join('<br>') + '</p>');
    панель.сообщение('Гриф — первым абзацем, справа: «' + части.join(' · ') + '»');
  } else {
    документ.задатьСтраницу({колонтитулы: {верхСправа: части.join(' · ')}});
    панель.сообщение('Гриф — в колонтитуле справа на каждой странице');
  }
  показатьСейчас();
}); }
function снятьАбзацГрифа(){
  const б = документ.блок(0);
  if(б && б.тег === 'P' && ГРИФЫ.test(б.текст) && б.текст.length < 300){ документ.удалить(0); return true; }
  return false;
}
function УбратьГриф(){ return безСбоя(() => {
  const к = (документ.страница || {}).колонтитулы || {};
  let было = 0;
  if(ГРИФЫ.test(к.верхСправа || '')){ документ.задатьСтраницу({колонтитулы: {верхСправа: ''}}); было++; }
  if(ГРИФЫ.test(к.верх || '')){ документ.задатьСтраницу({колонтитулы: {верх: ''}}); было++; }
  if(снятьАбзацГрифа()) было++;
  показатьСейчас();
  панель.сообщение(было ? 'Гриф убран' : 'Грифа не нашлось — ни в колонтитуле, ни первым абзацем');
}); }
/* экземпляры: для каждого номера — свой колонтитул, сборка в байты; после — колонтитул как был */
async function Экземпляры(){ return безСбоя(async () => {
  const п = параметры({});
  const n = Math.max(1, Math.min(200, +п.сколько || 1)), формат = п.формат === 'odt' ? 'odt' : 'docx';
  const было = Object.assign({}, (документ.страница || {}).колонтитулы || {});
  const имя = String(документ.имя || 'Документ').replace(/\.(docx|odt|plsd|txt)$/i, '').replace(/[\\/:*?"<>|]/g, ' ').trim() || 'Документ';
  const файлы = [];
  try {
    for(let k = 1; k <= n; k++){
      документ.задатьСтраницу({колонтитулы: {верхСправа: текстГрифа(Object.assign({}, п, {сНомером: true}), k).join(' · ')}});
      файлы.push({имя: имя + ' — экз. ' + String(k).padStart(String(n).length, '0') + '.' + формат, байты: await документ.собрать(формат)});
      if(n > 5) панель.сообщение('Собран экземпляр ' + k + ' из ' + n);
    }
  } finally {
    документ.задатьСтраницу({колонтитулы: {верхСправа: было.верхСправа || ''}});
  }
  const итог = await файл.выгрузитьАрхив(файлы, имя + ' — экземпляры');
  панель.сообщение(итог && итог.сохранено !== false ? 'Сохранено экземпляров: ' + n + ' (архив «' + имя + ' — экземпляры.zip»)' : 'Сохранение отменено');
}); }

/* ---------- заверение копии ---------- */
const ДАТА = д => { const m = String(д || '').match(/^(\d{4})-(\d{2})-(\d{2})/); if(m) return m[3] + '.' + m[2] + '.' + m[1]; const t = new Date(); return String(t.getDate()).padStart(2, '0') + '.' + String(t.getMonth() + 1).padStart(2, '0') + '.' + t.getFullYear(); };
const ПРОБЕЛЫ = n => ' '.repeat(n);
function отметка(){
  const п = параметры({});
  for(const k of ['должность', 'фио', 'организация', 'дело']) if(п[k]) хранилище.положить(k, п[k]);
  if(!String(п.фио || '').trim()) throw new Error('Впишите расшифровку подписи: И. О. Фамилия');
  const д = ДАТА(п.дата), год = String(п.годДела || '').trim() || д.slice(-4);
  const блоки = ['<p>' + экран(п.слово || 'Верно') + '</p>',
    '<p>' + экран(String(п.должность || '').trim()) + ПРОБЕЛЫ(6) + '________________' + ПРОБЕЛЫ(6) + экран(String(п.фио).trim()) + '</p>',
    '<p>' + д + '</p>'];
  if(п.сПодлинником){
    const орг = String(п.организация || '').trim();
    if(!орг) throw new Error('Впишите организацию, где хранится подлинник, — или снимите флажок');
    блоки.push('<p>Подлинник документа находится ' + экран(/^в[о]?\s/i.test(орг) ? орг : 'в ' + орг) + (String(п.дело || '').trim() ? ' в деле № ' + экран(String(п.дело).trim()) + ' за ' + экран(год) + ' год' : '') + '</p>');
  }
  return блоки;
}
function ЗаверитьВКонец(){ return безСбоя(() => {
  const блоки = отметка();
  документ.вставитьВКонец('<p></p>');
  for(const б of блоки) документ.вставитьВКонец(б);
  документ.перейти(документ.блоки.length - 1);
  панель.сообщение('Отметка о заверении — в конце документа');
}); }
/* несколько абзацев — следом за абзацем с курсором: вставка нескольких блоков в курсор сливает их в один абзац */
function ЗаверитьВКурсор(){ return безСбоя(() => {
  const блоки = отметка();
  const в = документ.выделение || {};
  let i = в.блок >= 0 ? в.блок + 1 : документ.блоки.length;
  for(const б of блоки) документ.вставить(i++, б);
  документ.перейти(i - 1);
  панель.сообщение('Отметка о заверении — после абзаца с курсором');
}); }
